    50  {
    51          if (m_Data == nullptr)
    52          {
    53                  PCPP_LOG_ERROR("Layer's data is NULL");
    54                  return false;
    55          }
    56
    57          if (m_Packet == nullptr)
    58          {
    59                  if ((size_t)offsetInLayer > m_DataLen)
    60                  {
    61                          PCPP_LOG_ERROR("Requested offset is larger than data length");
    62                          return false;
    63                  }
    64
    65                  uint8_t* newData = new uint8_t[m_DataLen + numOfBytesToExtend];
    66                  memcpy(newData, m_Data, offsetInLayer);
    67                  memcpy(newData + offsetInLayer + numOfBytesToExtend, m_Data + offsetInLayer, m_DataLen - offsetInLayer);
    68                  delete [] m_Data;
    69                  m_Data = newData;
    70                  m_DataLen += numOfBytesToExtend;
    71                  return true;
    72          }
    73
    74          return m_Packet->extendLayer(this, offsetInLayer, numOfBytesToExtend);
    75  }
