   246  uint16_t TcpLayer::calculateChecksum(bool writeResultToPacket)
   247  {
   248          tcphdr* tcpHdr = getTcpHeader();
   249          uint16_t checksumRes = 0;
   250          uint16_t currChecksumValue = tcpHdr->headerChecksum;
   251
   252          if (m_PrevLayer != nullptr)
   253          {
   254                  tcpHdr->headerChecksum = 0;
   255                  PCPP_LOG_DEBUG("TCP data len = " << m_DataLen);
   256
   257                  if (m_PrevLayer->getProtocol() == IPv4)
   258                  {
   259                          IPv4Address srcIP = ((IPv4Layer*)m_PrevLayer)->getSrcIPv4Address();
   260                          IPv4Address dstIP = ((IPv4Layer*)m_PrevLayer)->getDstIPv4Address();
   261
   262                          checksumRes = pcpp::computePseudoHdrChecksum((uint8_t *) tcpHdr, getDataLen(), IPAddress::IPv4AddressType,
   263                                                                                                  PACKETPP_IPPROTO_TCP, srcIP, dstIP);
   264
   265                          PCPP_LOG_DEBUG("calculated IPv4 TCP checksum = 0x" << std::uppercase << std::hex << checksumRes);
   266                  }
   267                  else if (m_PrevLayer->getProtocol() == IPv6)
   268                  {
   269                          IPv6Address srcIP = ((IPv6Layer*)m_PrevLayer)->getSrcIPv6Address();
   270                          IPv6Address dstIP = ((IPv6Layer*)m_PrevLayer)->getDstIPv6Address();
   271
   272                          checksumRes = computePseudoHdrChecksum((uint8_t *) tcpHdr, getDataLen(), IPAddress::IPv6AddressType,
   273                                                                                                     PACKETPP_IPPROTO_TCP, srcIP, dstIP);
   274
   275                          PCPP_LOG_DEBUG("calculated IPv6 TCP checksum = 0xX" << std::uppercase << std::hex << checksumRes);
   276                  }
   277          }
   278
   279          if(writeResultToPacket)
   280                  tcpHdr->headerChecksum = htobe16(checksumRes);
   281          else
   282                  tcpHdr->headerChecksum = currChecksumValue;
   283
   284          return checksumRes;
   285  }
